import app from 'flarum/forum/app';
import Page from 'flarum/common/components/Page';
import Button from 'flarum/common/components/Button';
import Link from 'flarum/common/components/Link';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
import { get, label, t, tx, icon } from '../util';
import { ContinueCard, Select, Tile } from './bits';
import { IndexSidebar, PageStructure } from './core';
import { openSeriesModal } from './SeriesModal';
const FORMATS = ['manga', 'webtoon', 'comic', 'manhwa', 'manhua'];
const SORTS = ['latest', 'new', 'trending', 'rating', 'followers', 'title'];
export const SHELVES = ['reading', 'planned', 'hold', 'completed', 'dropped', 'following'];

/**
 * /read: every series the member may see, filtered and sorted, with their series in progress on
 * top. /read/library: the member's own shelves. Built in core's page structure with the forum's
 * sidebar, so any theme dresses it.
 */
export default class LibraryPage extends Page {
  shelfMode = false;
  shelf = 'reading';
  q = '';
  format = '';
  status = '';
  genre = '';
  sort = 'latest';
  rows = [];
  cont = [];
  genres = [];
  stats = null;
  page = 1;
  more = false;
  loading = true;
  ticket = 0;
  typing = null;
  oninit(vnode) {
    super.oninit(vnode);
    this.shelfMode = app.current.get('routeName') === 'panels.library';
    this.bodyClass = 'App--panels';
    const p = k => String(m.route.param(k) || '');
    this.q = p('q');
    this.format = FORMATS.includes(p('format')) ? p('format') : '';
    this.genre = p('genre');
    this.sort = SORTS.includes(p('sort')) ? p('sort') : 'latest';
    this.shelf = SHELVES.includes(p('shelf')) ? p('shelf') : 'reading';
    const title = this.shelfMode ? tx('library.title') : label();
    app.history.push(this.shelfMode ? 'panels.library' : 'panels', title);
    app.setTitle(title);
    if (this.shelfMode && !app.session.user) {
      m.route.set(app.route('panels'));
      return;
    }
    if (!this.shelfMode) {
      get('genres', {}, true).then(r => this.genres = r.data).then(() => m.redraw(), () => {});
      get('feed', {
        kind: 'stats'
      }, true).then(r => this.stats = r.data).then(() => m.redraw(), () => {});
      if (app.session.user) get('feed', {
        kind: 'continue',
        limit: 3
      }, true).then(r => this.cont = r.data).then(() => m.redraw(), () => {});
    }
    this.load(1);
  }
  load(page) {
    const ticket = ++this.ticket;
    this.loading = true;
    const filter = {};
    if (this.shelfMode) filter.shelf = this.shelf;
    if (this.q) filter.q = this.q;
    if (this.format) filter.format = this.format;
    if (this.status) filter.status = this.status;
    if (this.genre) filter.genre = this.genre;
    get('series', {
      filter,
      sort: this.sort,
      page,
      limit: 24
    }).then(r => {
      if (ticket !== this.ticket) return;
      this.rows = page === 1 ? r.data : [...this.rows, ...r.data];
      this.more = r.hasMore;
      this.page = page;
    }).catch(() => {}).finally(() => {
      if (ticket !== this.ticket) return;
      this.loading = false;
      m.redraw();
    });
  }
  set(key, value) {
    this[key] = value;
    this.load(1);
  }
  view() {
    return m(PageStructure, {
      className: "PanelsLibrary",
      sidebar: () => m(IndexSidebar, null)
    }, this.header(), this.shelfMode ? this.shelfTabs() : this.toolbar(), !this.shelfMode && this.cont.length ? m("section", {
      className: "PanelsLibrary-section",
      "aria-labelledby": "panels-continue"
    }, m("div", {
      className: "PanelsLibrary-sectionHead"
    }, m("h2", {
      id: "panels-continue"
    }, t('continue_reading')), m(Link, {
      href: app.route('panels.library')
    }, t('library.title'))), m("div", {
      className: "PanelsLibrary-continue"
    }, this.cont.map(s => m(ContinueCard, {
      series: s
    })))) : null, m("section", {
      className: "PanelsLibrary-section",
      "aria-labelledby": "panels-grid"
    }, !this.shelfMode ? m("div", {
      className: "PanelsLibrary-sectionHead"
    }, m("h2", {
      id: "panels-grid"
    }, t(`sort.${this.sort}_heading`))) : m("h2", {
      id: "panels-grid",
      className: "visually-hidden"
    }, t(`library.${this.shelf}`)), this.rows.length ? m("div", {
      className: "PanelsGrid"
    }, this.rows.map(s => m(Tile, {
      series: s
    }))) : this.loading ? null : m("p", {
      className: "PanelsEmpty"
    }, this.shelfMode ? t('library.empty') : this.q || this.genre || this.format ? t('empty_filtered') : t('empty')), this.loading ? m(LoadingIndicator, null) : null, this.more && !this.loading ? m("div", {
      className: "PanelsMore"
    }, m(Button, {
      className: "Button",
      onclick: () => this.load(this.page + 1)
    }, t('load_more'))) : null), m("p", {
      className: "PanelsFoot"
    }, m(Link, {
      href: app.route('panels.copyright')
    }, t('copyright.link'))));
  }
  header() {
    const queue = Number(app.forum.attribute('panelsQueueCount') || 0);
    return m("header", {
      className: "PanelsLibrary-head"
    }, m("div", null, m("h1", null, this.shelfMode ? t('library.title') : label()), !this.shelfMode && this.stats ? m("p", {
      className: "PanelsMuted"
    }, t('stats_line', {
      series: this.stats.series,
      chapters: this.stats.chapters
    })) : null), m("div", {
      className: "PanelsLibrary-actions"
    }, app.forum.attribute('panelsCanModerate') ? m(Link, {
      className: "Button",
      href: app.route('panels.moderation')
    }, icon('fas fa-inbox', {
      className: 'Button-icon'
    }), m("span", {
      className: "Button-label"
    }, t('moderation.title'), queue ? m("span", {
      className: "PanelsBadge PanelsBadge--count"
    }, queue) : null)) : null, app.forum.attribute('panelsCanCreate') ? m(Button, {
      className: "Button Button--primary",
      icon: "fas fa-plus",
      onclick: () => openSeriesModal()
    }, t('start_series')) : null));
  }
  toolbar() {
    return m("div", {
      className: "PanelsToolbar"
    }, m("label", {
      className: "PanelsSearch"
    }, icon('fas fa-search'), m("span", {
      className: "visually-hidden"
    }, tx('search')), m("input", {
      className: "FormControl",
      type: "search",
      placeholder: tx('search'),
      value: this.q,
      oninput: e => {
        this.q = e.target.value;
        clearTimeout(this.typing);
        this.typing = setTimeout(() => this.load(1), 300);
      }
    })), m("div", {
      className: "PanelsChips",
      role: "group",
      "aria-label": tx('format_label')
    }, ['', ...FORMATS].map(f => m("button", {
      type: "button",
      className: 'PanelsChip' + (this.format === f ? ' is-on' : ''),
      "aria-pressed": this.format === f ? 'true' : 'false',
      onclick: () => this.set('format', f)
    }, f ? tx(`format.${f}`) : tx('all')))), m("div", {
      className: "PanelsFilters"
    }, m(Select, {
      label: tx('status_label'),
      value: this.status,
      options: [['', tx('status.any')], ...['ongoing', 'completed', 'hiatus', 'cancelled'].map(s => [s, tx(`status.${s}`)])],
      onchange: v => this.set('status', v)
    }), m(Select, {
      label: tx('genre_label'),
      value: this.genre,
      options: [['', tx('genre_any')], ...this.genres.map(g => [g.slug, g.name])],
      onchange: v => this.set('genre', v)
    }), m(Select, {
      label: tx('sort_label'),
      value: this.sort,
      options: SORTS.map(s => [s, tx(`sort.${s}`)]),
      onchange: v => this.set('sort', v)
    })));
  }
  shelfTabs() {
    return m("div", {
      className: "PanelsChips PanelsChips--tabs",
      role: "tablist"
    }, SHELVES.map(s => m("button", {
      type: "button",
      role: "tab",
      "aria-selected": this.shelf === s ? 'true' : 'false',
      className: 'PanelsChip' + (this.shelf === s ? ' is-on' : ''),
      onclick: () => this.set('shelf', s)
    }, t(`library.${s}`))));
  }
}
flarum.reg.add('ernestdefoe-panels', 'forum/pages/LibraryPage', LibraryPage);