import app from 'flarum/forum/app';
import Link from 'flarum/common/components/Link';
import Button from 'flarum/common/components/Button';
import humanTime from 'flarum/common/helpers/humanTime';
import { seriesHref, send, short, t, tx, icon } from '../util';

/*
 * Small pieces the pages share. Plain functions wrapped as { view } objects: a bare function in
 * JSX is a closure component factory in Mithril.
 */

/** A cover, or its colour while it loads. A blurred stand-in carries the 18+ mark. */
export const CoverArt = {
  view(vnode) {
    const {
      cover,
      color,
      title,
      size = 'medium'
    } = vnode.attrs;
    return m("span", {
      className: 'PanelsCover' + (cover?.blurred ? ' is-blurred' : ''),
      style: {
        backgroundColor: color || undefined
      }
    }, cover ? m("img", {
      src: cover[size],
      alt: cover.blurred ? '' : tx('cover_of', {
        title
      }),
      loading: "lazy",
      decoding: "async"
    }) : m("span", {
      className: "PanelsCover-empty"
    }, icon('fas fa-book-open')), cover?.blurred ? m("span", {
      className: "PanelsCover-gate"
    }, m("strong", null, "18+"), m("span", null, t('mature_cover'))) : null);
  }
};

/** A series in a grid: cover, format, NEW, title, latest chapter, rating. */
export const Tile = {
  view(vnode) {
    const s = vnode.attrs.series;
    const fresh = app.session.user ? s.unread > 0 : !!s.latestAt && Date.now() - Date.parse(s.latestAt) < 48 * 3600 * 1000;
    return m(Link, {
      className: "PanelsTile",
      href: seriesHref(s.slug)
    }, m("span", {
      className: "PanelsTile-art"
    }, m(CoverArt, {
      cover: s.cover,
      color: s.coverColor,
      title: s.title
    }), m("span", {
      className: "PanelsBadge PanelsBadge--format"
    }, tx(`format.${s.format}`)), fresh ? m("span", {
      className: "PanelsBadge PanelsBadge--new"
    }, t('new')) : null), m("strong", {
      className: "PanelsTile-title"
    }, s.title), m("span", {
      className: "PanelsTile-meta"
    }, m("span", null, s.latest ? [short(s.format, s.latest.number), ' · ', humanTime(s.latest.publishedAt)] : tx(`status.${s.status}`)), s.rating ? m("span", {
      className: "PanelsTile-rating"
    }, "\u2605 ", s.rating.toFixed(1)) : null));
  }
};

/** A series in progress: where the member is, and how much is new. */
export const ContinueCard = {
  view(vnode) {
    const s = vnode.attrs.series;
    const p = s.progress;
    const pct = p && p.pages ? Math.min(100, Math.round(p.page / p.pages * 100)) : 0;
    const href = p ? app.route('panels.reader', {
      slug: s.slug,
      chapter: p.number
    }) : seriesHref(s.slug);
    return m(Link, {
      className: "PanelsContinue",
      href: href
    }, m("span", {
      className: "PanelsContinue-art"
    }, m(CoverArt, {
      cover: s.cover,
      color: s.coverColor,
      title: s.title,
      size: "small"
    })), m("span", {
      className: "PanelsContinue-body"
    }, m("span", {
      className: "PanelsContinue-head"
    }, m("strong", null, s.title), s.unread ? m("span", {
      className: "PanelsBadge PanelsBadge--count"
    }, t('n_new', {
      count: s.unread
    })) : null), m("span", {
      className: "PanelsContinue-where"
    }, p ? t('place', {
      chapter: short(s.format, p.number),
      page: p.page,
      pages: p.pages
    }) : null), m("span", {
      className: "PanelsBar",
      "aria-hidden": "true"
    }, m("span", {
      style: {
        width: `${pct}%`
      }
    })), m("span", {
      className: "PanelsContinue-cta"
    }, t('continue'))));
  }
};

/** Five stars a member can set (or clear by choosing the same one again). */
export const StarPicker = {
  view(vnode) {
    const {
      value,
      onchange,
      disabled
    } = vnode.attrs;
    return m("span", {
      className: "PanelsStars",
      role: "group",
      "aria-label": tx('rate')
    }, [1, 2, 3, 4, 5].map(n => m("button", {
      type: "button",
      className: 'PanelsStars-star' + ((value || 0) >= n ? ' is-on' : ''),
      "aria-label": tx('stars', {
        count: n
      }),
      "aria-pressed": value === n ? 'true' : 'false',
      disabled: disabled,
      onclick: () => onchange(value === n ? null : n)
    }, "\u2605")));
  }
};

/** Ask the member to confirm they're 18+, then run `done`. */
export function confirmAdult(done) {
  if (!app.session.user) {
    app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'));
    return;
  }
  if (!window.confirm(tx('age.confirm'))) return;
  send('POST', 'age').then(() => {
    app.forum.pushAttributes({
      panelsAdult: true
    });
    done();
  });
}

/** Why a member can't read something, as a card with the next step. */
export const Refusal = {
  view(vnode) {
    const {
      refusal,
      offer,
      onretry
    } = vnode.attrs;
    let action = null;
    if (refusal === 'signin') {
      action = m(Button, {
        className: "Button Button--primary",
        onclick: () => app.modal.show(() => flarum.reg.asyncModuleImport('flarum/forum/components/LogInModal'))
      }, app.translator.trans('core.forum.header.log_in_link'));
    } else if (refusal === 'age') {
      action = m(Button, {
        className: "Button Button--primary",
        onclick: () => confirmAdult(onretry)
      }, t('age.button'));
    } else if (refusal === 'paid' && offer) {
      const Locked = globalThis.flarum?.reg?.get?.('ernestdefoe-kiosk', 'forum/components/LockedNotice');
      const LockedNotice = Locked?.default || Locked;
      // Each renders nothing when no product sells it: a chapter on its own, or the whole series.
      if (LockedNotice) action = [m(LockedNotice, {
        type: "panels-chapter",
        id: offer.chapter
      }), m(LockedNotice, {
        type: "panels-series",
        id: offer.series
      })];
    }
    return m("div", {
      className: `PanelsRefusal PanelsRefusal--${refusal}`,
      role: "status"
    }, m("span", {
      className: "PanelsRefusal-icon"
    }, icon(refusal === 'paid' ? 'fas fa-lock' : refusal === 'unreleased' ? 'far fa-clock' : 'fas fa-eye-slash')), m("h2", null, t(`refusal.${refusal}.title`)), m("p", null, t(`refusal.${refusal}.body`)), action);
  }
};

/** A select styled like core's: label, then the native control (accessible and phone-friendly). */
export const Select = {
  view(vnode) {
    const {
      label,
      value,
      options,
      onchange,
      className
    } = vnode.attrs;
    return m("label", {
      className: 'PanelsSelect ' + (className || '')
    }, m("span", {
      className: "visually-hidden"
    }, label), m("select", {
      className: "FormControl",
      value: value,
      "aria-label": label,
      onchange: e => onchange(e.target.value)
    }, options.map(([v, l]) => m("option", {
      value: v,
      selected: v === value
    }, l))));
  }
};
flarum.reg.add('ernestdefoe-panels', 'forum/pages/bits', { CoverArt: CoverArt,Tile: Tile,ContinueCard: ContinueCard,StarPicker: StarPicker,confirmAdult: confirmAdult,Refusal: Refusal,Select: Select, });